34	// setupHandoverableParent 准备：登记 10.000 毫升原样 → 成功分出 3.250 毫升
35	// 子样（原样剩余 6.750）→ 子样经交接由别人在别处确认持有。原样无待确认
36	// 交接、未销毁，当前持有人仍在记录地点，拟用的交接编号尚未占用。
37	func setupHandoverableParent(t *testing.T) *handoverSaveFixture {
38		t.Helper()
39		dir := t.TempDir()
40		path := filepath.Join(dir, "data.json")
41	
42		s, err := Open(path)
43		if err != nil {
44			t.Fatalf("open: %v", err)
45		}
46		clock := time.Date(2026, 10, 2, 9, 0, 0, 0, time.UTC)
47		s.now = func() time.Time { return clock }
48	
49		const parentID, childID, transferID = "P", "C0", "TR-P"
50		mustRegister(t, s, parentID, "10.000", "张三", "实验室A")
51		if _, err := s.Split(SplitInput{ParentID: parentID, Parts: []SplitPart{
52			{ID: childID, Qty: "3.250"},
53		}}); err != nil {
54			t.Fatalf("前置分装: %v", err)
55		}
56	
57		// 原有子样交接给别人、在别处确认：它有独立于原样的数量、持有人、
58		// 地点和保管历史（分出 → 交出 → 接收）。
59		cHAt := clock.Add(time.Hour)
60		cRAt := cHAt.Add(time.Hour)
61		if _, err := s.Handover(HandoverInput{
62			TransferID: "TR-C0", SampleID: childID,
63			FromHolder: "张三", FromLocation: "实验室A",
64			ToHolder: "李四", ToLocation: "实验室B",
65			HandedOverAt: cHAt,
66		}); err != nil {
67			t.Fatalf("前置交接发起: %v", err)
68		}
69		if _, err := s.Confirm(ConfirmInput{"TR-C0", "李四", "实验室B", cRAt}); err != nil {
70			t.Fatalf("前置交接确认: %v", err)
71		}
72	
73		// 本次交出时间晚于全部已有历史，请求本身完全合法。
74		hAt := clock.Add(4 * time.Hour)
75	
76		parentBefore, err := s.GetSample(parentID)
77		if err != nil {
78			t.Fatal(err)
79		}
80		childBefore, err := s.GetSample(childID)
81		if err != nil {
82			t.Fatal(err)
83		}
84		disk, err := os.ReadFile(path)
85		if err != nil {
86			t.Fatalf("read persisted data: %v", err)
87		}
88	
89		// 前置条件自检：原样初始 10.000、剩余 6.750、无待确认、未销毁，
90		// 持有人和地点仍是登记记录；拟用交接编号尚未占用；原有子样独立持有。
91		if parentBefore.InitialQty != "10.000" || parentBefore.Remaining != "6.750" ||
92			parentBefore.Holder != "张三" || parentBefore.Location != "实验室A" ||
93			parentBefore.PendingTransfer != nil || parentBefore.Destruction != nil {
94			t.Fatalf("前置原样状态不正确: %+v", parentBefore)
95		}
96		if len(parentBefore.Children) != 1 || parentBefore.Children[0] != childID ||
97			len(parentBefore.History) != 2 {
98			t.Fatalf("前置原样的子样与历史不正确: %+v", parentBefore)
99		}
100		if childBefore.InitialQty != "3.250" || childBefore.Remaining != "3.250" ||
101			childBefore.ParentID != parentID ||
102			childBefore.Holder != "李四" || childBefore.Location != "实验室B" ||
103			len(childBefore.History) != 3 {
104			t.Fatalf("前置原有子样状态不正确: %+v", childBefore)
105		}
106		if _, err := s.GetTransfer(transferID); !errors.Is(err, ErrNotFound) {
107			t.Fatalf("前置交接编号 %q 应尚未占用", transferID)
108		}
109	
110		return &handoverSaveFixture{
111			dir: dir, path: path, s: s, hAt: hAt,
112			parentID: parentID, childID: childID, transferID: transferID,
113			in: HandoverInput{
114				TransferID: transferID, SampleID: parentID,
115				FromHolder: "张三", FromLocation: "实验室A",
116				ToHolder: "王五", ToLocation: "实验室C",
117				HandedOverAt: hAt,
118			},
119			parentBefore: parentBefore,
120			childBefore:  childBefore,
121			diskBefore:   disk,
122		}
