125	// assertHandoverDidNotTakeEffect 断言一次保存失败的交接完全没有生效：
126	// 原样逐项保持提交前状态、没有待确认详情与本次交出历史，交接编号仍未
127	// 占用，原有子样保持自己的数量与保管状态。
128	func assertHandoverDidNotTakeEffect(t *testing.T, f *handoverSaveFixture) {
129		t.Helper()
130	
131		parent, err := f.s.GetSample(f.parentID)
132		if err != nil {
133			t.Fatalf("get parent: %v", err)
134		}
135		if !reflect.DeepEqual(parent, f.parentBefore) {
136			t.Fatalf("保存失败后原样状态被改动:\n before=%+v\n after =%+v",
137				f.parentBefore, parent)
138		}
139		// 关键业务字段再逐项点明：初始量、剩余量、持有人、地点、子样关系。
140		if parent.InitialQty != "10.000" || parent.Remaining != "6.750" {
141			t.Fatalf("原样数量不应被失败的交接改动: init=%s remaining=%s",
142				parent.InitialQty, parent.Remaining)
143		}
144		if parent.Holder != "张三" || parent.Location != "实验室A" {
145			t.Fatalf("原样持有人和地点不应变化: %s @ %s", parent.Holder, parent.Location)
146		}
147		if len(parent.Children) != 1 || parent.Children[0] != f.childID {
148			t.Fatalf("原样子样关系不应变化: %v", parent.Children)
149		}
150		if parent.PendingTransfer != nil {
151			t.Fatalf("失败的交接不得留下待确认详情（不能让重试被误当成已发起）: %+v",
152				parent.PendingTransfer)
153		}
154		if parent.Destruction != nil {
155			t.Fatalf("失败的交接不得引入销毁信息: %+v", parent.Destruction)
156		}
157		// 保管历史中不得出现本次交出事件，长度与内容都停留在提交前。
158		if len(parent.History) != len(f.parentBefore.History) {
159			t.Fatalf("失败的交接不得追加历史: before=%d after=%d",
160				len(f.parentBefore.History), len(parent.History))
161		}
162		for _, h := range parent.History {
163			if h.Kind == "transfer-out" && strings.Contains(h.Detail, f.transferID) {
164				t.Fatalf("保管历史中不应出现本次交出事件: %+v", h)
165			}
166		}
167	
168		// 交接记录完全不存在：按编号查询必须得到记录不存在错误。
169		if tr, err := f.s.GetTransfer(f.transferID); !errors.Is(err, ErrNotFound) {
170			t.Fatalf("失败的交接不应占用编号 %s, got view=%+v err=%v",
171				f.transferID, tr, err)
172		}
173	
174		// 已分出的子样仍保留自己的数量与保管状态，不随原样进入待确认。
175		child, err := f.s.GetSample(f.childID)
176		if err != nil {
177			t.Fatalf("get existing child: %v", err)
178		}
179		if !reflect.DeepEqual(child, f.childBefore) {
180			t.Fatalf("原有子样不应被原样的失败交接带动:\n before=%+v\n after =%+v",
181				f.childBefore, child)
182		}
183		if child.PendingTransfer != nil {
184			t.Fatalf("子样不应随原样进入待确认状态: %+v", child.PendingTransfer)
185		}
186	}
